import test from 'node:test';
import assert from 'node:assert/strict';
import {spawn} from 'node:child_process';
import {fileURLToPath} from 'node:url';
import {testServer} from '../../server/test/helpers.js';
import {createIssue} from '../../server/src/modules/work/issues.js';
test('pinned hierarchy browser explores keyboard depth later pages and delayed resource switches',{timeout:65000},async()=>{
  const server=await testServer();let child;
  try{
    const api=server.agent(),auth=await api('POST','/auth/signup',{name:'Tree browser',email:'tree-browser@example.test',password:'correct-horse-battery'}),user=auth.data.user,org=(await api('POST','/orgs',{name:'Tree browser'})).data.organization;
    const project=(await api('POST','/orgs/'+org.id+'/projects',{key:'TREE',name:'Tree browser'})).data.project,cross=(await api('POST','/orgs/'+org.id+'/projects',{key:'OTHER',name:'Other tree'})).data.project;
    const create=body=>createIssue(server.ctx,{user},project.id,body),root=create({title:'Explore root'}),children=[];
    for(let n=0;n<23;n++)children.push(create({title:'Nested '+n,parentId:root.id}));
    const deep=create({title:'Deep leaf',parentId:children.at(-1).id});for(let n=0;n<24;n++)create({title:'Other root '+n});
    createIssue(server.ctx,{user},cross.id,{title:'Other project root'});
    const settings={url:server.url,cookie:auth.cookie,projectId:project.id,crossId:cross.id,rootId:root.id,firstChildId:children.at(-1).id,deepId:deep.id};
    const result=await new Promise((resolve,reject)=>{
      child=spawn('/usr/bin/python3',[fileURLToPath(new URL('./issue-hierarchy-browser.py',import.meta.url)),JSON.stringify(settings)],{detached:true});let stdout='',stderr='';
      const timer=setTimeout(()=>{try{process.kill(-child.pid,'SIGKILL');}catch{}reject(new Error('Hierarchy browser exceeded 55 seconds'));},55000);
      child.stdout.on('data',value=>stdout+=value);child.stderr.on('data',value=>stderr+=value);child.on('error',error=>{clearTimeout(timer);reject(error);});child.on('close',code=>{clearTimeout(timer);resolve({code,stdout,stderr});});
    });assert.equal(result.code,0,result.stderr);assert.equal(JSON.parse(result.stdout.trim()).ok,true);
  }finally{if(child?.pid){try{process.kill(-child.pid,'SIGKILL');}catch{}}await server.close();}
});
